// Minimal C++ binding to the ABI generated by Godot 4.7.2, x64.
// RefCounted + fifteen methods; no godot-cpp runtime or STL ABI
// crosses the DLL boundary. Godot owns all StringName/String/Variant storage.
#include "gdextension_interface.h"
#include "window_bridge.hpp"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <new>

namespace {
using Type = GDExtensionVariantType;
constexpr Type nil = GDEXTENSION_VARIANT_TYPE_NIL;
constexpr Type boolean = GDEXTENSION_VARIANT_TYPE_BOOL;
constexpr Type integer = GDEXTENSION_VARIANT_TYPE_INT;
constexpr Type real = GDEXTENSION_VARIANT_TYPE_FLOAT;
constexpr Type vector2i = GDEXTENSION_VARIANT_TYPE_VECTOR2I;
constexpr Type string = GDEXTENSION_VARIANT_TYPE_STRING;
static_assert(sizeof(void *) == 8, "PetWindowBridge requires x64");
static_assert(sizeof(pet3d::DesktopPoint) == 8);

struct Api {
    GDExtensionClassLibraryPtr library{};
    GDExtensionInterfaceStringNameNewWithUtf8Chars name_new{};
    GDExtensionInterfaceStringNewWithUtf8Chars string_new{};
    GDExtensionInterfaceStringToUtf8Chars string_utf8{};
    GDExtensionInterfaceVariantGetPtrDestructor destructor{};
    GDExtensionInterfaceVariantNewNil new_nil{};
    GDExtensionInterfaceVariantGetType variant_type{};
    GDExtensionInterfaceGetVariantFromTypeConstructor from{};
    GDExtensionInterfaceGetVariantToTypeConstructor to{};
    GDExtensionInterfaceClassdbRegisterExtensionClass6 register_class{};
    GDExtensionInterfaceClassdbRegisterExtensionClassMethod register_method{};
    GDExtensionInterfaceClassdbUnregisterExtensionClass unregister_class{};
    GDExtensionInterfaceClassdbConstructObject3 construct{};
    GDExtensionInterfaceObjectSetInstance set_instance{};
    GDExtensionInterfaceClassdbGetMethodBind get_method{};
    GDExtensionInterfaceObjectMethodBindPtrcall ptrcall{};
    GDExtensionMethodBindPtr notification{};
} api;

struct Name {
    alignas(void *) unsigned char data[8]{}; // float_64 StringName in engine dump
    explicit Name(const char *text) { api.name_new(data, text); }
    ~Name() { api.destructor(GDEXTENSION_VARIANT_TYPE_STRING_NAME)(data); }
    Name(const Name &) = delete;
    Name &operator=(const Name &) = delete;
};
struct String {
    alignas(void *) unsigned char data[8]{};
    explicit String(const char *text) { api.string_new(data, text); }
    explicit String(GDExtensionConstVariantPtr variant) {
        api.to(string)(data, const_cast<GDExtensionVariantPtr>(variant));
    }
    ~String() { api.destructor(GDEXTENSION_VARIANT_TYPE_STRING)(data); }
    String(const String &) = delete;
    String &operator=(const String &) = delete;
};

std::string read_string(GDExtensionConstStringPtr value) {
    const auto size = api.string_utf8(value, nullptr, 0);
    std::string text(static_cast<size_t>(size), '\0');
    if (size) api.string_utf8(value, text.data(), size);
    return text;
}

enum class Method { configure, interactive, cursor, dpi, left_down, begin, end, captured, poll, shutdown,
    acquire, adopt, terminate, displays, menu_actions, hotkeys };
struct MethodSpec {
    const char *name;
    Method id;
    Type result;
    Type argument;
    const char *argument_name;
};
MethodSpec methods[] = {
    {"configure", Method::configure, boolean, integer, "hwnd"},
    {"set_interactive", Method::interactive, nil, boolean, "interactive"},
    {"get_cursor_position", Method::cursor, vector2i, nil, ""},
    {"get_dpi_scale", Method::dpi, real, nil, ""},
    {"is_left_button_down", Method::left_down, boolean, nil, ""},
    {"begin_capture", Method::begin, boolean, nil, ""},
    {"end_capture", Method::end, nil, nil, ""},
    {"has_capture", Method::captured, boolean, nil, ""},
    {"poll_tray_action", Method::poll, integer, nil, ""},
    {"shutdown", Method::shutdown, nil, nil, ""},
    {"acquire_instance", Method::acquire, integer, string, "key"},
    {"adopt_service_process", Method::adopt, boolean, integer, "pid"},
    {"terminate_service_processes", Method::terminate, nil, nil, ""},
    {"get_displays_json", Method::displays, string, nil, ""},
    {"set_menu_actions", Method::menu_actions, boolean, string, "groups"},
    {"configure_hotkeys", Method::hotkeys, integer, string, "spec"},
};

// Output storage is explicitly typed and copied to avoid aliasing Godot types.
struct Value {
    int64_t number = 0;
    double decimal = 0.0;
    GDExtensionBool flag = 0;
    pet3d::DesktopPoint point{};
    std::string text;
    void *address(Type type) {
        if (type == boolean) return &flag;
        if (type == vector2i) return &point;
        if (type == real) return &decimal;
        return &number;
    }
};

Value invoke(Method id, pet3d::WindowBridge *bridge, const Value &argument) {
    Value result;
    switch (id) {
        case Method::configure: result.flag = bridge->configure(argument.number); break;
        case Method::interactive: bridge->set_interactive(argument.flag != 0); break;
        case Method::cursor: result.point = bridge->get_cursor_position(); break;
        case Method::dpi: result.decimal = bridge->get_dpi_scale(); break;
        case Method::left_down: result.flag = bridge->is_left_button_down(); break;
        case Method::begin: result.flag = bridge->begin_capture(); break;
        case Method::end: bridge->end_capture(); break;
        case Method::captured: result.flag = bridge->has_capture(); break;
        case Method::poll: result.number = bridge->poll_tray_action(); break;
        case Method::shutdown: bridge->shutdown(); break;
        case Method::acquire: result.number = bridge->acquire_instance(argument.text); break;
        case Method::adopt: result.flag = bridge->adopt_service_process(argument.number); break;
        case Method::terminate: bridge->terminate_service_processes(); break;
        case Method::displays: result.text = bridge->get_displays_json(); break;
        case Method::menu_actions: result.flag = bridge->set_menu_actions(argument.text); break;
        case Method::hotkeys: {
            unsigned values[4] = {};
            const char *cursor = argument.text.c_str();
            int parsed = 0;
            while (parsed < 4 && *cursor) {
                char *end = nullptr;
                const unsigned long value = std::strtoul(cursor, &end, 10);
                if (end == cursor) break;
                values[parsed++] = static_cast<unsigned>(value);
                cursor = (*end == ',') ? end + 1 : end;
            }
            if (parsed != 4) break;
            result.number = bridge->configure_hotkeys(
                    values[0], values[1], values[2], values[3]);
            break;
        }
    }
    return result;
}

void call(void *userdata, GDExtensionClassInstancePtr instance,
        const GDExtensionConstVariantPtr *args, GDExtensionInt count,
        GDExtensionVariantPtr ret, GDExtensionCallError *error) {
    const auto &method = *static_cast<MethodSpec *>(userdata);
    *error = {};
    error->error = GDEXTENSION_CALL_OK;
    const int expected = method.argument == nil ? 0 : 1;
    if (!instance || count != expected) {
        error->error = !instance ? GDEXTENSION_CALL_ERROR_INSTANCE_IS_NULL :
                count < expected ? GDEXTENSION_CALL_ERROR_TOO_FEW_ARGUMENTS :
                                   GDEXTENSION_CALL_ERROR_TOO_MANY_ARGUMENTS;
        error->expected = expected;
        api.new_nil(ret);
        return;
    }
    Value argument;
    if (expected) {
        if (api.variant_type(args[0]) != method.argument) {
            error->error = GDEXTENSION_CALL_ERROR_INVALID_ARGUMENT;
            error->argument = 0;
            error->expected = method.argument;
            api.new_nil(ret);
            return;
        }
        if (method.argument == string) {
            String text(args[0]); // Variant conversion constructs into uninitialized storage.
            argument.text = read_string(text.data);
        } else {
            api.to(method.argument)(argument.address(method.argument), const_cast<GDExtensionVariantPtr>(args[0]));
        }
    }
    auto value = invoke(method.id, static_cast<pet3d::WindowBridge *>(instance), argument);
    if (method.result == nil) api.new_nil(ret);
    else if (method.result == string) {
        String text(value.text.c_str());
        api.from(string)(ret, text.data);
    }
    else api.from(method.result)(ret, value.address(method.result));
}

void ptrcall(void *userdata, GDExtensionClassInstancePtr instance,
        const GDExtensionConstTypePtr *args, GDExtensionTypePtr ret) {
    const auto &method = *static_cast<MethodSpec *>(userdata);
    Value argument;
    if (method.argument == integer) std::memcpy(&argument.number, args[0], sizeof(argument.number));
    if (method.argument == boolean) std::memcpy(&argument.flag, args[0], sizeof(argument.flag));
    if (method.argument == string) argument.text = read_string(args[0]);
    auto value = invoke(method.id, static_cast<pet3d::WindowBridge *>(instance), argument);
    if (!ret) return;
    if (method.result == integer) std::memcpy(ret, &value.number, sizeof(value.number));
    if (method.result == boolean) std::memcpy(ret, &value.flag, sizeof(value.flag));
    if (method.result == vector2i) std::memcpy(ret, &value.point, sizeof(value.point));
    if (method.result == real) std::memcpy(ret, &value.decimal, sizeof(value.decimal));
    if (method.result == string) {
        // ptrcall uses initialized TypePtr return storage, unlike Variant call's
        // constructor output. Replace that String and leave its new value owned
        // by Godot; never memcpy refcounted String storage or return STL memory.
        api.destructor(string)(ret);
        api.string_new(ret, value.text.c_str());
    }
}

GDExtensionObjectPtr create(void *, GDExtensionBool notify_postinitialize) {
    pet3d::WindowBridge *bridge = nullptr;
    try { bridge = new pet3d::WindowBridge; }
    catch (const std::bad_alloc &) { return nullptr; }
    Name parent("RefCounted"), name("PetWindowBridge");
    auto object = api.construct(parent.data); // 4.7 construct3 starts with refcount 1
    if (!object) { delete bridge; return nullptr; }
    api.set_instance(object, name.data, bridge);
    if (notify_postinitialize) {
        const int64_t notification = 0; // Object::NOTIFICATION_POSTINITIALIZE
        const GDExtensionBool reversed = false;
        const GDExtensionConstTypePtr args[] = {&notification, &reversed};
        api.ptrcall(api.notification, object, args, nullptr);
    }
    return object;
}

void free_instance(void *, GDExtensionClassInstancePtr instance) {
    delete static_cast<pet3d::WindowBridge *>(instance);
}

void initialize(void *, GDExtensionInitializationLevel level) {
    if (level != GDEXTENSION_INITIALIZATION_SCENE) return;
    Name name("PetWindowBridge"), parent("RefCounted"), object("Object"), notification("notification");
    api.notification = api.get_method(object.data, notification.data, 4023243586);
    GDExtensionClassCreationInfo6 info{};
    info.is_exposed = true;
    info.create_instance_func = create;
    info.free_instance_func = free_instance;
    api.register_class(api.library, name.data, parent.data, &info);
    for (auto &method : methods) {
        Name method_name(method.name), argument_name(method.argument_name), empty("");
        String hint("");
        GDExtensionPropertyInfo result{};
        result.type = method.result;
        result.name = empty.data;
        result.class_name = empty.data;
        result.hint_string = hint.data;
        result.usage = 6; // PROPERTY_USAGE_DEFAULT
        auto argument = result;
        argument.name = argument_name.data;
        argument.type = method.argument;
        auto metadata = method.argument == integer ? GDEXTENSION_METHOD_ARGUMENT_METADATA_INT_IS_INT64 :
                                                    GDEXTENSION_METHOD_ARGUMENT_METADATA_NONE;
        GDExtensionClassMethodInfo binding{};
        binding.name = method_name.data;
        binding.method_userdata = &method;
        binding.call_func = call;
        binding.ptrcall_func = ptrcall;
        binding.method_flags = GDEXTENSION_METHOD_FLAG_NORMAL;
        binding.has_return_value = method.result != nil;
        binding.return_value_info = &result;
        binding.return_value_metadata = method.result == integer ? GDEXTENSION_METHOD_ARGUMENT_METADATA_INT_IS_INT64 :
                                        method.result == real ? GDEXTENSION_METHOD_ARGUMENT_METADATA_REAL_IS_DOUBLE :
                                                                 GDEXTENSION_METHOD_ARGUMENT_METADATA_NONE;
        binding.argument_count = method.argument == nil ? 0 : 1;
        binding.arguments_info = &argument;
        binding.arguments_metadata = &metadata;
        api.register_method(api.library, name.data, &binding);
    }
}

void deinitialize(void *, GDExtensionInitializationLevel level) {
    if (level != GDEXTENSION_INITIALIZATION_SCENE) return;
    Name name("PetWindowBridge");
    api.unregister_class(api.library, name.data);
}
}

extern "C" __declspec(dllexport) GDExtensionBool pet_window_library_init(
        GDExtensionInterfaceGetProcAddress get_proc, GDExtensionClassLibraryPtr library,
        GDExtensionInitialization *initialization) {
    api.library = library;
#define LOAD(field, type, symbol) \
    api.field = reinterpret_cast<type>(get_proc(symbol)); \
    if (!api.field) return false
    LOAD(name_new, GDExtensionInterfaceStringNameNewWithUtf8Chars, "string_name_new_with_utf8_chars");
    LOAD(string_new, GDExtensionInterfaceStringNewWithUtf8Chars, "string_new_with_utf8_chars");
    LOAD(string_utf8, GDExtensionInterfaceStringToUtf8Chars, "string_to_utf8_chars");
    LOAD(destructor, GDExtensionInterfaceVariantGetPtrDestructor, "variant_get_ptr_destructor");
    LOAD(new_nil, GDExtensionInterfaceVariantNewNil, "variant_new_nil");
    LOAD(variant_type, GDExtensionInterfaceVariantGetType, "variant_get_type");
    LOAD(from, GDExtensionInterfaceGetVariantFromTypeConstructor, "get_variant_from_type_constructor");
    LOAD(to, GDExtensionInterfaceGetVariantToTypeConstructor, "get_variant_to_type_constructor");
    LOAD(register_class, GDExtensionInterfaceClassdbRegisterExtensionClass6, "classdb_register_extension_class6");
    LOAD(register_method, GDExtensionInterfaceClassdbRegisterExtensionClassMethod, "classdb_register_extension_class_method");
    LOAD(unregister_class, GDExtensionInterfaceClassdbUnregisterExtensionClass, "classdb_unregister_extension_class");
    LOAD(construct, GDExtensionInterfaceClassdbConstructObject3, "classdb_construct_object3");
    LOAD(set_instance, GDExtensionInterfaceObjectSetInstance, "object_set_instance");
    LOAD(get_method, GDExtensionInterfaceClassdbGetMethodBind, "classdb_get_method_bind");
    LOAD(ptrcall, GDExtensionInterfaceObjectMethodBindPtrcall, "object_method_bind_ptrcall");
#undef LOAD
    initialization->minimum_initialization_level = GDEXTENSION_INITIALIZATION_SCENE;
    initialization->userdata = nullptr;
    initialization->initialize = initialize;
    initialization->deinitialize = deinitialize;
    return true;
}
